refentry.refsect1:
&reftitle.description;
public voidIo\Poll\Watcher::modifyData mixeddata
Replaces the data associated with the watcher. The watched events are left unchanged.

&reftitle.parameters;


  data


    The new value to associate with the watcher.

&reftitle.errors;

 Throws an Io\Poll\InactiveWatcherException
 if the watcher is no longer active.

  &reftitle.examples;

   Io\Poll\Watcher::modifyData example


<?php
use Io\Poll\Context;
use Io\Poll\Event;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($reader), [Event::Read], 'connecting');
var_dump($watcher->getData());

$watcher->modifyData('connected');
var_dump($watcher->getData());


   &example.outputs;


string(10) "connecting"
string(9) "connected"
